export const pairs=[["Menü","Menu"],["Hauptnavigation","Main navigation"],["Zynora Studio öffnen","Open Zynora Studio"],["Herunterladen","Download"],["Impressum","Legal notice"],["Mein Profil","My profile"],["DEIN NÄCHSTER TRACK BEGINNT HIER","YOUR NEXT TRACK STARTS HERE"],["aus ideen","turn ideas"],["wird","into"],["Ein Beat im Kopf. Ein Sample, das hängen bleibt. Mach etwas Eigenes daraus — mit deinem Musikstudio für unterwegs.","A beat in your head. A sample you cannot forget. Turn it into something of your own — with your music studio on the go."],["Android-App","Android app"],["Dein Rhythmus. Dein Raum. Dein ZYNORA.","Your rhythm. Your space. Your ZYNORA."],["01 / 09 · Songstudio","01 / 09 · Song Studio"],["●   VON DER IDEE ZUM TRACK","● FROM IDEA TO TRACK"],["VON DER IDEE ZUM TRACK","FROM IDEA TO TRACK"],["ANDROID-APP · ECHTE ANSICHT","ANDROID APP · ACTUAL APP SCREEN"],["Weniger warten.","Less waiting."],["Mehr Musik.","More music."],["DEIN KREATIVER SPIELRAUM","YOUR CREATIVE PLAYGROUND"],["Alles beginnt","Everything starts"],["mit einem","with a"],["Moment.","moment."],["Sampler und Songstudio gehören zusammen: Spiele deine Sounds auf den Pads und entwickle daraus dein eigenes Arrangement.","Sampler and Song Studio belong together: play your sounds on the pads and turn them into your own arrangement."],["01 / ARRANGIEREN","01 / ARRANGE"],["Gib deiner Idee","Give your idea"],["eine Richtung.","a direction."],["Audio- und Notenclips, mehrere Spuren und eine Timeline. Aus einzelnen Sounds wird dein Song.","Audio and note clips, multiple tracks and a timeline. Turn individual sounds into your song."],["02 / SPIELEN","02 / PLAY"],["Fühl den Beat.","Feel the beat."],["Samples auf den Pads spielen, Patterns entwickeln und den nächsten Groove finden.","Play samples on the pads, build patterns and discover your next groove."],["03 / KOMPONIEREN","03 / COMPOSE"],["Eine Note weiter.","One note further."],["Melodien und Akkorde in der Piano Roll bearbeiten und eigene Klangideen ausprobieren.","Edit melodies and chords in the piano roll and explore your own musical ideas."],["DEIN KONTO. DEIN ZUGANG.","YOUR ACCOUNT. YOUR ACCESS."],["Dein Sound braucht","Your sound needs"],["ein","a"],["Zuhause.","home."],["Ein Konto für die Browser-Beta, den Android-Download und dein Profil. Dein Benutzername gehört nur dir.","Your profile and unique username are your first step. Studio access and APK downloads will open later."],["Konto erstellen","Create account"],["Mach es zu deinem.","Make it yours."],["Mit E-Mail registrieren und Adresse bestätigen.","Sign up with your email and verify your address."],["Finde deinen Namen.","Find your name."],["Einen einmaligen Benutzernamen wählen und dein Profilbild hinzufügen.","Choose a unique username and add your profile picture."],["Leg los.","Get started."],["Die Browser-Beta öffnen oder die Android-App herunterladen.","Studio access and APK downloads are being prepared."],["AUSBLICK","COMING LATER"],["Heute deine Ideen.","Your ideas today."],["Später unsere","Our future"],["Öffentliche Songs, geteilte Samples und ein Marketplace sind für später geplant. Aktuell werden keine Songs oder Samples öffentlich im Profil geteilt.","Public songs, shared samples and a marketplace are planned for later. Songs and samples are not currently shared publicly on profiles."],["Deinen ersten Beat starten ↗","Start your first beat ↗"],["SAMPLER + SONGSTUDIO","SAMPLER + SONG STUDIO"],["öffnen.","open."],["Deine Sounds auf den Pads. Deine Ideen im Songstudio. Zwei Wege, Musik zu machen — ein Zynora Studio.","Your sounds on the pads. Your ideas in Song Studio. Two ways to make music — one Zynora Studio."],["01 / SONGSTUDIO","01 / SONG STUDIO"],["ANDROID-ANSICHT","ANDROID SCREEN"],["Ein Pad.","One pad."],["Ein neuer Groove.","A new groove."],["Spiele deine Samples, finde einen Rhythmus und mach ihn zu deinem.","Play your samples, find a rhythm and make it your own."],["Die Bilder zeigen die Android-App. Die Browser-Beta ist eine eigene erste Web-Umsetzung.","These images show the Android app. The browser beta is a separate initial web implementation."],["BROWSER-BETA","BROWSER BETA"],["Dein Sound.","Your sound."],["Dein Studio.","Your studio."],["Starte mit 16 Sampler-Pads, vier Sequencer-Spuren und deinem eigenen Tempo. Lade eigene Audios und exportiere deinen Beat als WAV.","Start with 16 sampler pads, four sequencer tracks and your own tempo. Import audio and export your beat as WAV."],["Zynora Studio öffnen ↗","Open Zynora Studio ↗"],["♧ Erstelle jetzt ein Konto, um Zynora Studio zu öffnen.","♧ Create an account to open Zynora Studio."],["Die Browser-Beta enthält aktuell den Web-Sampler mit Step-Sequencer. Die vollständige native Songstudio-Timeline, Piano Roll und Cloud-Synchronisierung sind noch nicht übertragen.","The browser beta currently includes the web sampler and step sequencer. The full native Song Studio timeline, piano roll and cloud sync have not been ported yet."],["MUSIK ZUM MITNEHMEN","TAKE YOUR MUSIC WITH YOU"],["Immer dabei.","Always with you."],["Die vorhandene Android-App direkt als APK herunterladen.","Download the existing Android app directly as an APK."],["ZYNORA für Android","ZYNORA for Android"],["Sampler und Songstudio für deine musikalischen Ideen. Die bestehende APK trägt noch den Namen NEXORA STUDIO.","Sampler and Song Studio for your musical ideas. The existing APK still carries the name NEXORA STUDIO."],["24,8 MiB","24.8 MiB"],["APK herunterladen ↓","Download APK ↓"],["♧ Erstelle jetzt ein Konto, um die APK herunterzuladen.","♧ Create an account to download the APK."],["Eine APK installierst du außerhalb des Play Stores. Sichere vorhandene Projekte vor einem Update.","An APK is installed outside the Play Store. Back up existing projects before updating."],["Veröffentlichung folgt noch.","Release coming later."],["GEPLANT","PLANNED"],["Veröffentlichung folgt noch. Aktuell kein iOS-Build.","Release coming later. No iOS build is currently available."],["Die Store-Einträge sind noch nicht verfügbar.","Store listings are not available yet."],["DEIN PLATZ BEI ZYNORA","YOUR PLACE AT ZYNORA"],["Hallo,","Hello,"],["kreativer Kopf.","creative mind."],["Deine Ideen. Dein Profil.","Your ideas. Your profile."],["Einmal anmelden — Browser-Beta und Android-Download freischalten.","Create your profile. Studio access and APK downloads will become available later."],["Konto erstellen ↗","Create account ↗"],["Du hast schon ein Konto? Anmelden","Already have an account? Sign in"],["Profilbild auswählen","Choose profile picture"],["JPG, PNG oder WebP · wird vor dem Upload verkleinert.","JPG, PNG or WebP · resized before uploading."],["Benutzername","Username"],["3–24 Zeichen: kleine Buchstaben, Ziffern und Unterstrich. Jeder Name ist einmalig.","3–24 characters: lowercase letters, numbers and underscores. Every username is unique."],["Anzeigename","Display name"],["Profil speichern ↗","Save profile ↗"],["Abmelden","Sign out"],["SPÄTER","LATER"],["Hier finden später deine veröffentlichten Songs und Samples ihren Platz. Im Moment ist dein Profil nur für dich sichtbar; ein öffentlicher Marketplace ist noch nicht aktiv.","Your published songs and samples will appear here in the future. For now, your profile is visible only to you; the public marketplace is not active."],["ANBIETERANGABEN","PROVIDER INFORMATION"],["Private Vorschau: Anbieterangaben müssen vor dem öffentlichen Start ergänzt werden.","Private preview: provider details must be completed before the public launch."],["Für ein vollständiges Impressum fehlen noch der vollständige Name beziehungsweise die Firma des Betreibers, eine ladungsfähige Anschrift und eine tatsächlich erreichbare Kontaktadresse.","The legal notice still requires the operator’s full name or company name, a postal address for legal correspondence and a working contact address."],["Die gewünschte Domain zynora-studio.com und die dazugehörige E-Mail-Adresse sind noch nicht eingerichtet. Weitere Angaben hängen von der Rechtsform und der Tätigkeit des Betreibers ab.","The requested domain zynora-studio.com and its domain email address are not configured yet. Further details depend on the operator’s legal structure and activities."],["TRANSPARENT MIT DEINEN DATEN","TRANSPARENT ABOUT YOUR DATA"],["Verarbeitung von Daten","Data processing"],["Entwurf zur Verarbeitung von Daten für die private Vorschau · Stand 04.11.2026. Verantwortlicher, Kontakt, Hostingvertrag und Aufbewahrungsfristen sind vor öffentlichem Betrieb zu vervollständigen.","Draft data processing information for the private preview · 4 November 2026. Controller, contact details, hosting arrangements and retention periods must be completed before public operation."],["1. Verantwortlicher","1. Data controller"],["Die vollständigen Angaben des Betreibers und eine erreichbare Datenschutz-Kontaktadresse müssen noch ergänzt werden. Die geplante Domain und Mailadresse sind derzeit nicht aktiv.","The operator’s full details and an accessible privacy contact must still be added. The planned domain and domain email address are not active."],["2. Konto und E-Mail-Bestätigung","2. Account and email verification"],["Für Registrierung und Anmeldung werden E-Mail-Adresse, Passwort, technische Sitzungsdaten und der Zeitpunkt der E-Mail-Bestätigung über Supabase Auth verarbeitet. Das Passwort wird durch den Authentifizierungsdienst geschützt verarbeitet und ist nicht im Profil sichtbar. Die Bestätigungsnachricht dient der Prüfung deiner E-Mail-Adresse. Der produktive Mailanbieter ist noch festzulegen.","Registration and sign-in process your email address, password, technical session data and email verification time through Supabase Auth. Passwords are securely processed by the authentication service and are not visible in profiles. Verification messages confirm your email address. The production email provider has not been selected yet."],["3. Benutzername und Profilbild","3. Username and profile picture"],["Dein eindeutiger Benutzername, Anzeigename und optionales Profilbild werden mit deiner Konto-ID im Supabase-Projekt gespeichert. Das Projekt liegt in der Region Frankfurt (eu-central-1). Bilder werden im Browser verkleinert und als JPEG ohne übernommene EXIF-Metadaten hochgeladen. Der private Bildspeicher erlaubt Zugriffe nur nach den eingerichteten Berechtigungen. Im bestehenden App-System können angemeldete Mitglieder Profile über die Profilsuche finden; diese Website zeigt derzeit nur das eigene Profil.","Your unique username, display name and optional profile picture are stored with your account ID in the Supabase project, located in Frankfurt (eu-central-1). Images are resized in your browser and uploaded as JPEG without retaining EXIF metadata. Private image storage restricts access according to configured permissions. In the existing app system, signed-in members can find profiles through profile search; this website currently displays only your own profile."],["4. Rechtsgrundlagen und Empfänger","4. Legal bases and recipients"],["Die für das angeforderte Konto notwendigen Daten dienen der Bereitstellung des Dienstes (Art. 6 Abs. 1 lit. b DSGVO). Sicherheits- und Betriebsdaten dienen dem sicheren Betrieb (Art. 6 Abs. 1 lit. f DSGVO); die konkrete Abwägung ist durch den Betreiber zu dokumentieren. Dienstleister sind der Website-Hoster, Supabase und nach Einrichtung der Mailanbieter. Auftragsverarbeitung, mögliche Drittlandzugriffe und geeignete Garantien sind vor Veröffentlichung abschließend zu dokumentieren.","Data necessary for the requested account is processed to provide the service (Article 6(1)(b) GDPR). Security and operational data supports secure operation (Article 6(1)(f) GDPR); the operator must document the relevant balancing assessment. Service providers include the website host, Supabase and, once configured, the email provider. Processing agreements, possible third-country access and appropriate safeguards must be fully documented before publication."],["5. Lokale Browserdaten und Musik","5. Local browser data and music"],["Für die Anmeldung speichert die Website die notwendige Supabase-Sitzung im lokalen Browserspeicher. Die Browser-Beta speichert Patterns nur auf deinem Gerät und nach Benutzerkonto getrennt. Importierte Audios werden lokal verarbeitet und nicht als Profilinhalt hochgeladen. Beim WAV-Export wird eine lokale Datei erzeugt. Beim Abmelden endet die Sitzung; gespeicherte lokale Patterns bleiben auf dem Gerät. Über die Studio-Funktion „Pattern löschen“ oder das Löschen der Website-Daten kannst du sie entfernen.","The website stores the necessary Supabase sign-in session in local browser storage. The browser beta saves patterns only on your device, separately for each account. Imported audio is processed locally and is not uploaded to your profile. WAV export creates a local file. Signing out ends the session; saved local patterns remain on your device. Remove them using “Clear pattern” in the studio or by clearing the website’s browser data."],["6. Hosting, Download und technische Dienste","6. Hosting, downloads and technical services"],["Beim Aufruf entstehen notwendige Verbindungsdaten wie IP-Adresse, Zeitpunkt und aufgerufene Ressource beim Hoster. Der APK-Download wird über Supabase nach Prüfung des angemeldeten Kontos bereitgestellt. Es werden keine Werbe- oder Analyse-Tracker eingebaut. Schriftarten stammen vom Gerät; die verwendete Supabase-Bibliothek wird mit der Website ausgeliefert.","The host processes necessary connection information such as IP address, time and requested resource. APK downloads are provided through Supabase after verifying the signed-in account. No advertising or analytics trackers are included. Fonts come from your device, and the Supabase library is served with the website."],["7. Speicherdauer und Löschung","7. Retention and deletion"],["Kontodaten bleiben grundsätzlich für die Dauer des Kontos gespeichert. Konkrete Fristen für Betriebsprotokolle, Backups und Löschaufträge müssen vom Betreiber noch festgelegt werden. Ein erreichbarer Kontakt und ein geprüfter Prozess für Konto- und Datenlöschung fehlen noch und sind Voraussetzung für den öffentlichen Start.","Account data is generally retained for the lifetime of the account. The operator must still define specific retention periods for logs, backups and deletion requests. An accessible contact and a verified account and data deletion process are required before public launch."],["8. Deine Rechte","8. Your rights"],["Im Rahmen der gesetzlichen Voraussetzungen bestehen Rechte auf Auskunft, Berichtigung, Löschung, Einschränkung, Datenübertragbarkeit und Widerspruch sowie auf Beschwerde bei einer zuständigen Datenschutzaufsichtsbehörde. Soweit eine Verarbeitung auf Einwilligung beruht, kannst du diese für die Zukunft widerrufen.","Subject to applicable legal requirements, you have rights of access, rectification, erasure, restriction, portability and objection, and the right to complain to a competent data protection authority. Where processing relies on consent, you may withdraw it for the future."],["9. Spätere Community-Funktionen","9. Future community features"],["Öffentliche Songs, Sample-Uploads und Marketplace sind derzeit nicht aktiv. Vor ihrer Einführung werden Sichtbarkeit, Nutzungsrechte und Datenschutzinformationen gesondert festgelegt. Die Android-App hat einen eigenen Funktions- und Datenschutzumfang.","Public songs, sample uploads and the marketplace are not currently active. Visibility, usage rights and privacy information will be specified separately before launch. The Android app has its own feature set and privacy scope."],["Ein Raum für deinen Sound.","A space for your sound."],["© 2026 ZYNORA Studio · Private Vorschau","© 2026 ZYNORA Studio · Pre-launch"],["WILLKOMMEN BEI ZYNORA","WELCOME TO ZYNORA"],["Anmelden","Sign in"],["E-Mail-Adresse","Email address"],["Einmalig · 3–24 kleine Buchstaben, Ziffern oder Unterstrich","Unique · 3–24 lowercase letters, numbers or underscores"],["Passwort","Password"],["Ich habe folgende Hinweise gelesen:","I have read the"],["Hinweise zur Verarbeitung von Daten","data processing information"],["Passwort vergessen?","Forgot password?"],["ZYNORA / BROWSER-BETA","ZYNORA / BROWSER BETA"],["Dein nächster Beat.","Your next beat."],["Vollbild ↗","Fullscreen ↗"],["Speichern","Save"],["WAV exportieren ↓","Export WAV ↓"],["Pattern löschen","Clear pattern"],["Tippen oder Tasten 1–4, Q–R, A–F, Y–V","Tap or use keys 1–4, Q–R, A–F, Y–V"],["16 Schritte · 1 Takt","16 steps · 1 bar"],["Pro Spur kannst du ein eigenes Sample importieren. Audio bleibt auf diesem Gerät. Eigene Samples nach dem Neustart erneut laden.","Import your own sample for each track. Audio stays on this device. Reload imported samples after restarting."],["Diese Beta ist ein eigenständiger Web-Sampler. Native Timeline, Piano Roll, Zusammenarbeit und Android-Projektformate sind noch nicht übertragen.","This beta is a standalone web sampler. The native timeline, piano roll, collaboration and Android project formats have not been ported yet."],["Schließen","Close"],["Studio schließen","Close studio"],["Zynora Studio kennenlernen","Discover Zynora Studio"],["Karussell","Carousel"],["Feature-Auswahl","Feature selection"],["Vorheriges Feature","Previous feature"],["Nächstes Feature","Next feature"],["Timeline der Android-App","Android app timeline"],["Songstudio der Android-App mit mehrspuriger Timeline","Android Song Studio with a multitrack timeline"],["Sampler der Android-App mit Soundpads und Klangreglern","Android sampler with sound pads and controls"],["ZYNORA Studio — Aus Ideen wird Sound.","ZYNORA Studio — Turn ideas into sound."],["Aus Ideen wird Sound. — ZYNORA Studio","Turn ideas into sound. — ZYNORA Studio"],["Zynora Studio öffnen — ZYNORA Studio","Open Zynora Studio — ZYNORA Studio"],["Herunterladen — ZYNORA Studio","Download — ZYNORA Studio"],["Mein Profil — ZYNORA Studio","My profile — ZYNORA Studio"],["Impressum & Verarbeitung von Daten — ZYNORA Studio","Legal notice & data processing — ZYNORA Studio"],["Neues Passwort.","New password."],["Schön, dass du da bist.","Good to see you."],["Passwort speichern ↗","Save password ↗"],["Anmelden ↗","Sign in ↗"],["Dieser Benutzername ist bereits vergeben. Bitte wähle einen anderen.","This username is already taken. Please choose another."],["E-Mail-Adresse oder Passwort stimmen nicht.","The email address or password is incorrect."],["Bitte bestätige zuerst deine E-Mail-Adresse.","Please verify your email address first."],["Zu viele E-Mail-Anfragen. Bitte warte etwas und versuche es erneut.","Too many email requests. Please wait before trying again."],["Der E-Mail-Versand ist aktuell auf Testadressen beschränkt. Der Betreiber muss einen eigenen Mailversand einrichten.","Email delivery is currently limited to test addresses. The operator needs to configure a production email service."],["Bitte prüfe deine E-Mail-Adresse.","Please check your email address."],["Die Verbindung konnte nicht hergestellt werden. Bitte versuche es erneut.","Could not connect. Please try again."],["Die Bestätigungs-E-Mail konnte nicht versendet werden. Der Betreiber muss den Mailversand prüfen.","The verification email could not be sent. The operator needs to check email delivery."],["Kontoverbindung noch nicht verfügbar. Bitte lade die Seite erneut.","The account connection is not ready. Please reload the page."],["Wähle zuerst deinen einmaligen Benutzernamen und speichere dein Profil.","Choose your unique username and save your profile first."],["Kontoverbindung ist noch nicht bereit.","The account connection is not ready yet."],["Einen Moment …","One moment …"],["Dein Passwort wurde gespeichert.","Your password has been saved."],["Dieser Benutzername ist nicht verfügbar.","This username is not available."],["Konto erstellt. Bitte vervollständige dein Profil.","Account created. Please complete your profile."],["Bitte prüfe dein E-Mail-Postfach und bestätige deine Adresse. Dein Benutzername wird beim Speichern des Profils verbindlich vergeben.","Please check your inbox and verify your address. Your username is reserved when you save your profile."],["Willkommen bei ZYNORA.","Welcome to ZYNORA."],["Falls ein Konto existiert, wurde ein Link zum Zurücksetzen angefordert. Bitte prüfe dein Postfach.","If an account exists, a password reset link has been requested. Please check your inbox."],["Profil wird gespeichert …","Saving your profile …"],["Bitte gib einen Anzeigenamen ein.","Please enter a display name."],["Dein Profil wurde gespeichert.","Your profile has been saved."],["Dein Profil ist bereit.","Your profile is ready."],["Bitte wähle ein JPG-, PNG- oder WebP-Bild bis 15 MB.","Please choose a JPG, PNG or WebP image up to 15 MB."],["Das Bild ist noch zu groß. Bitte wähle ein anderes.","The image is still too large. Please choose another."],["Bild ausgewählt. Klicke auf „Profil speichern“, um es hochzuladen.","Image selected. Click “Save profile” to upload it."],["Du bist abgemeldet.","You are signed out."],["Dein Download wird vorbereitet …","Preparing your download …"],["Der Download ist noch nicht eingerichtet.","The download has not been configured yet."],["Download gestartet.","Download started."],["Die Kontobibliothek konnte nicht geladen werden.","The account library could not be loaded."],["Kontoverbindung derzeit nicht verfügbar.","The account connection is currently unavailable."],["Dein Browser unterstützt hier keinen Vollbildmodus.","Your browser does not support fullscreen here."],["Dein Profilbild","Your profile picture"],["Eigenes Audio für diese Spur importieren","Import audio for this track"],["Bitte wähle eine Audiodatei bis 20 MB.","Please choose an audio file up to 20 MB."],["Bitte wähle ein Sample bis 30 Sekunden.","Please choose a sample up to 30 seconds."],["Eigenes Sample geladen. Es bleibt lokal und muss nach einem Neustart erneut geladen werden.","Your sample has been loaded. It stays local and must be reloaded after restarting."],["Pattern auf diesem Gerät gespeichert. Eigene Audiodateien sind nicht Teil dieser Speicherung.","Pattern saved on this device. Imported audio files are not included."],["Das Pattern konnte nicht gespeichert werden. Möglicherweise ist der Browserspeicher voll.","Could not save the pattern. Your browser storage may be full."],["WAV wird gerendert …","Rendering WAV …"],["WAV exportiert. Dein Beat wurde nicht hochgeladen.","WAV exported. Your beat was not uploaded."],["Sounds werden geladen …","Loading sounds …"],["Sample-Liste nicht erreichbar","The sample list could not be loaded"],["Sample nicht erreichbar","The sample could not be loaded"],["Bereit. Tippe auf ein Pad oder starte den Sequencer.","Ready. Tap a pad or start the sequencer."],["Pattern geleert und gespeicherte Fassung auf diesem Gerät entfernt.","Pattern cleared and the saved version removed from this device."],["Songstudio","Song Studio"],["Eigene Samples","Your samples"],["Projekte","Projects"],["WAV-Export","WAV export"],["deine samples.","your samples."],["dein","your"],["sound.","sound."],["EIGENE AUDIOS IMPORTIEREN","IMPORT YOUR OWN AUDIO"],["Lade deine eigenen Samples ins Studio. Importiere Audiodateien und verwende sie im Sampler oder im Songstudio — lokal auf deinem Gerät.","Bring your own samples into the studio. Import audio files and use them in the sampler or Song Studio — locally on your device."],["EIGENE DATEIEN · DEINE SOUND-BIBLIOTHEK","YOUR FILES · YOUR SOUND LIBRARY"],["spiel deinen","play your"],["eigenen","own"],["beat.","beat."],["16 PADS. DEIN RHYTHMUS.","16 PADS. YOUR RHYTHM."],["Spiele Samples auf den Pads, probiere neue Kombinationen aus und forme deinen Groove mit Reglern und Effekten.","Play samples on the pads, try new combinations and shape your groove with controls and effects."],["SAMPLER · SPIELEN UND AUSPROBIEREN","SAMPLER · PLAY AND EXPLORE"],["aus noten","turn notes"],["gefühl.","feeling."],["MELODIEN UND AKKORDE","MELODIES AND CHORDS"],["Zeichne Noten in der Piano Roll. Verschiebe Tonhöhen, ändere Längen und entwickle die Melodie, die dir im Kopf geblieben ist.","Draw notes in the piano roll. Change pitches and note lengths, and develop the melody you cannot get out of your head."],["PIANO ROLL · DEINE MELODIE","PIANO ROLL · YOUR MELODY"],["schritt für","step by"],["schritt zum","step to the"],["PATTERNS MIT DEM STEP-SEQUENCER","PATTERNS WITH THE STEP SEQUENCER"],["Setze deine Drums Schritt für Schritt. Kombiniere Kick, Hats und Percussion zu eigenen Patterns und finde deinen Rhythmus.","Build your drums step by step. Combine kicks, hats and percussion into your own patterns and find your rhythm."],["STEP-SEQUENCER · DEIN NÄCHSTES PATTERN","STEP SEQUENCER · YOUR NEXT PATTERN"],["dein sound.","your sound."],["in","in"],["bewegung.","motion."],["KLANGVERLÄUFE GESTALTEN","SHAPE HOW YOUR SOUND EVOLVES"],["Zeichne Automationskurven für Filter und weitere Klangparameter. So verändern sich deine Sounds mit dem Verlauf deines Tracks.","Draw automation curves for filters and other sound parameters. Let your sounds evolve throughout your track."],["AUTOMATION · KURVEN STATT STILLSTAND","AUTOMATION · KEEP YOUR SOUND MOVING"],["dein mix.","your mix."],["moment.","moment."],["LIVE-DJ IN DER ANDROID-APP","LIVE DJ IN THE ANDROID APP"],["Entdecke den Live-DJ-Bereich der Android-App und bringe deine Sounds in einen neuen Zusammenhang.","Explore Live DJ in the Android app and bring your sounds together in a new way."],["LIVE-DJ · DEIN SOUND IM MIX","LIVE DJ · YOUR SOUND IN THE MIX"],["halte deine","save your"],["ideen","ideas"],["fest.","for later."],["PROJEKTE SPEICHERN UND WEITERBAUEN","SAVE PROJECTS AND KEEP CREATING"],["Speichere deine Projekte in der Android-App, öffne sie später wieder und arbeite weiter, wenn die nächste Idee kommt.","Save your projects in the Android app, open them again later and keep creating when your next idea comes."],["PROJEKTE · DEINE IDEEN BLEIBEN EDITIERBAR","PROJECTS · KEEP YOUR IDEAS EDITABLE"],["dein track.","your track."],["deine","your"],["datei.","file."],["ALS WAV EXPORTIEREN","EXPORT AS WAV"],["Exportiere deine Musik als WAV-Datei. Die Android-App bietet auch den Export einzelner Spuren; die Browser-Beta exportiert deinen Sequencer-Beat.","Export your music as a WAV file. The Android app also exports individual tracks; the browser beta exports your sequencer beat."],["WAV-EXPORT · VOM STUDIO ZUR AUDIODATEI","WAV EXPORT · FROM STUDIO TO AUDIO FILE"],["Songstudio der Android-App: farbige Spuren auf einer Timeline","Android Song Studio: coloured tracks on a timeline"],["Soundauswahl mit dem Button Eigene Datei importieren in der Android-App","Android sound picker with an Import your own file button"],["Soundbibliothek der Android-App mit Suche, Kategorien und Sound-Zuweisung","Android sound library with search, categories and sound assignment"],["Piano Roll der Android-App mit Klaviertasten und editierbaren Noten","Android piano roll with piano keys and editable notes"],["Step-Sequencer der Android-App mit großen Pads und Rhythmusschritten","Android step sequencer with large pads and rhythm steps"],["Automation der Android-App mit einer bearbeitbaren Filter-Cutoff-Kurve","Android automation with an editable filter cutoff curve"],["Live-DJ-Oberfläche der vorhandenen Android-App","Live DJ in the existing Android app"],["Projekt- und Speicherplatzauswahl der Android-App","Android project and save-slot selection"],["Songstudio der Android-App mit einem arrangierten mehrspurigen Projekt","Android Song Studio with an arranged multitrack project"],["Songstudio anzeigen","Show Song Studio"],["Eigene Samples anzeigen","Show your samples"],["Sampler anzeigen","Show sampler"],["Piano Roll anzeigen","Show piano roll"],["Step-Sequencer anzeigen","Show step sequencer"],["Automation anzeigen","Show automation"],["Live-DJ anzeigen","Show Live DJ"],["Projekte anzeigen","Show projects"],["WAV-Export anzeigen","Show WAV export"],["ZYNORA Studio – dein Raum für Beats, Samples und neue Ideen. Entdecke die Android-App und die Browser-Beta.","ZYNORA Studio — your space for beats, samples and new ideas. Discover the Android app and browser beta."],["10. Sprache und Länderhinweis","10. Language and country suggestion"],["Der Hoster stellt für den Sprachhinweis das aus der Verbindung abgeleitete Land bereit. Die Website verwendet nur den Ländercode, fragt kein GPS ab und übermittelt die IP-Adresse nicht an einen zusätzlichen Ortungsdienst. Die Spracheinstellung und die Entscheidung zum Hinweis werden lokal im Browser gespeichert. Die Ländererkennung kann beispielsweise durch VPNs ungenau sein.","The host provides a country derived from the connection for the language suggestion. The website uses only the country code, does not request GPS and does not send your IP address to an additional location service. Your language preference and response to the suggestion are stored locally in your browser. Country detection can be inaccurate, for example when using a VPN."],["DATEN & ANBIETERANGABEN","DATA & PROVIDER INFORMATION"],["Impressum","Legal notice"],["Direkt zu Anbieter und Kontakt ↓","Go directly to provider and contact details ↓"],["Verarbeitung von Daten","Data processing"],["Private Vorbereitung · 5. November 2026. Hosting, Mailversand und Löschverfahren müssen vor dem öffentlichen Start abschließend eingerichtet werden.","Pre-launch · 5 November 2026. This website is hosted on GitHub Pages. Studio access and APK downloads are paused. Mail delivery and account deletion procedures are still being finalized."],["1. Verantwortlicher und Kontakt","1. Controller and contact"],["Verantwortlich für diese Website ist Yorick Arlt. Anschrift und Kontaktdaten stehen weiter unten. Für Datenschutzanfragen: zynora-studio@outlook.de.","Yorick Arlt is responsible for this website. Full address and contact details are provided below. For privacy requests, contact zynora-studio@outlook.de."],["2. Konto und Profil","2. Account and profile"],["Supabase Auth verarbeitet E-Mail-Adresse, Passwort, Bestätigungs- und Sitzungsdaten zur Bereitstellung deines Kontos. Einmaliger Benutzername, Anzeigename und optionales Profilbild werden im Projekt NEXORA STUDIO in Frankfurt gespeichert. Passwörter werden nicht im Profil angezeigt. Profilbilder werden im Browser verkleinert und in JPEG umgewandelt. Diese Website zeigt derzeit nur dein eigenes Profil an.","Supabase Auth processes your email address, password, verification and session data to provide your account. Your unique username, display name and optional profile picture are stored in the NEXORA STUDIO project in Frankfurt. Passwords are not displayed in profiles. Profile pictures are resized and converted to JPEG in your browser. This website currently displays only your own profile."],["3. Notwendige Speicherung auf deinem Gerät","3. Necessary storage on your device"],["Die Website speichert Anmeldesitzung, Spracheinstellung und die Bestätigung des Speicherhinweises in deinem Browser. Im Sampler speichert IndexedDB benannte Projekte, Patterns, Tempo und importierte Audiodateien getrennt nach Konto. Änderungen werden automatisch gespeichert. Projekte liegen ausschließlich in diesem Browser auf diesem Gerät: Es gibt keine Synchronisation mit Android, anderen Geräten oder einer anderen Domain. Exportiere Projekt-Sicherungen vor einem Domainwechsel oder dem Löschen von Browserdaten. Abmelden löscht lokale Projekte nicht.","The website stores your sign-in session, language preference and acknowledgement of the storage notice in your browser. When you use the sampler, IndexedDB stores named projects, patterns, tempo and imported audio separately for each account. Autosave runs after changes. These projects are stored only in this browser on this device: they do not sync with Android, another device or a different domain. Export project backups before changing domains or clearing browser data. Signing out does not erase local projects."],["Es gibt keine Werbe- oder Analyse-Tracker. Die Speicherung für Konto und Sampler ist für die von dir angeforderten Funktionen erforderlich (§ 25 Abs. 2 Nr. 2 TDDDG). Der Speicherhinweis ist eine Kenntnisnahme, keine Einwilligung in Tracking. Du kannst abbrechen und öffentliche Seiten weiter nutzen. Lokale Projekte lassen sich über die Projekt-Löschfunktion oder durch Löschen der Browserdaten dieser Website entfernen.","There are no advertising or analytics trackers. The storage used for the account and sampler is necessary for the functions you request (§ 25(2)(2) TDDDG); the storage notice is an acknowledgement, not consent to tracking. You may cancel and continue browsing public pages. Delete local projects with the project deletion button or by clearing this website’s browser data."],["4. Zwecke und Rechtsgrundlagen","4. Purposes and legal bases"],["Konto- und Profildaten werden zur Bereitstellung der angeforderten Leistung verarbeitet (Art. 6 Abs. 1 Buchst. b DSGVO). Notwendige Sicherheits- und Betriebsverarbeitung beruht auf dem berechtigten Interesse an einem sicheren Betrieb (Art. 6 Abs. 1 Buchst. f DSGVO). Öffentliches Teilen und ein Marketplace sind noch nicht aktiv. Importierte Samples werden lokal dekodiert; WAV-Export und Projekt-Sicherung erzeugen lokale Dateien.","Account and profile data are processed to provide the service you request (Article 6(1)(b) GDPR). Necessary security and operational processing is based on the legitimate interest in secure operation (Article 6(1)(f) GDPR). Optional public sharing and a marketplace are not active. Imported samples are decoded locally; WAV export and project backup create local files."],["5. Hosting, Downloads und E-Mail","5. Hosting, downloads and email"],["Der Hoster verarbeitet Verbindungsdaten wie IP-Adresse, Zeitpunkt und angeforderte Ressource für Auslieferung und Sicherheit. Supabase stellt Anmeldung, Profile, private Profilbilder und geschützte APK-Downloads bereit. Gewünschter Absender für Konto-E-Mails ist support@zynora-studio.com; diese Versandanbindung ist noch nicht betriebsbereit. Öffentlicher Hoster, Auftragsverarbeitungsverträge, Aufbewahrungseinstellungen und gegebenenfalls Garantien für Drittlandübermittlungen müssen vor Veröffentlichung abschließend festgelegt werden.","The host processes connection information such as IP address, request time and resource for delivery and security. Supabase provides authentication, profiles, private avatars and protected APK downloads. The desired authentication sender is support@zynora-studio.com; this delivery integration is not yet operational. GitHub Pages hosts the public website. Processing agreements, retention settings and any international transfer safeguards for the services must still be finalized before account services launch."],["6. Sprachvorschlag","6. Language suggestion"],["Soweit unterstützt, liefert der Hoster einen aus der Verbindung abgeleiteten Ländercode für den Deutschvorschlag. Andernfalls verwendet der Vorschlag Browsersprache und Zeitzone; dein tatsächlicher Standort wird dabei nicht festgestellt. GPS und zusätzliche IP-Ortungsdienste werden nicht verwendet. Deine Sprachauswahl wird lokal gespeichert.","Where supported, the host supplies a country code derived from the connection to suggest German. Otherwise the suggestion uses your browser language and time zone; it does not determine your actual location. No GPS or additional IP location service is used. Your language choice is stored locally."],["7. Aufbewahrung, Löschung und deine Rechte","7. Retention, deletion and your rights"],["Kontodaten werden gespeichert, solange dein Konto benötigt wird, vorbehaltlich gesetzlicher Aufbewahrungspflichten. Über die unten genannte Kontaktadresse kannst du Kontolöschung sowie gegebenenfalls Auskunft, Berichtigung, Löschung, Einschränkung, Datenübertragbarkeit und Widerspruch verlangen. Du kannst dich bei der zuständigen Datenschutzaufsicht beschweren, insbesondere beim Hessischen Beauftragten für Datenschutz und Informationsfreiheit. Konkrete Protokoll- und Backup-Fristen sowie ein geprüftes Löschverfahren sind noch Voraussetzungen für den Start. Lokale Projekte bleiben bis zur Löschung oder zum Entfernen der Browserdaten erhalten; auch der Browser kann Speicher freigeben. Bewahre unabhängige Sicherungen auf.","Account data is retained while your account is needed, subject to applicable legal retention duties. Contact the address below to request account deletion or exercise your rights of access, rectification, erasure, restriction, portability and objection where applicable. You may complain to the competent data protection authority, including the Hessian Commissioner for Data Protection and Freedom of Information. Specific log and backup retention periods and the verified deletion process remain launch requirements. Local projects remain until you delete them or clear browser data; browser eviction may also remove them. Keep independent backups."],["ANBIETER & KONTAKT","PROVIDER & CONTACT"],["Inhaber der Website und inhaltlich verantwortlich","Website owner and responsible for content"],["E-Mail","Email"],["Bei Fragen zu dieser Website, Datenschutz oder deinem Konto nutze bitte diese Kontaktadresse.","For questions about this website, privacy or your account, please use this contact address."],["Starte mit dem Sampler im Browser. Die Android-App enthält zusätzlich das Songstudio.","Start with the sampler in your browser. The Android app also includes Song Studio."],["Projekt","Project"],["Projektname","Project name"],["Neues Projekt","New project"],["Projekt sichern ↓","Back up project ↓"],["Projekt importieren","Import project"],["Projekt löschen","Delete project"],["Importiere Audio für jede Spur. Projekte und Samples werden automatisch in diesem Browser gespeichert. Exportiere eine Projekt-Sicherung als unabhängige Kopie.","Import audio for each track. Projects and samples are saved automatically in this browser. Export a project backup to keep a separate copy."],["DEIN GERÄT. DEINE PROJEKTE.","YOUR DEVICE. YOUR PROJECTS."],["Bevor du fortfährst","Before you continue"],["Dein Konto benötigt lokalen Anmeldespeicher. Der Sampler speichert Projekte und importierte Samples in diesem Browser auf diesem Gerät. Es gibt keine Cloud-Synchronisation. Es werden keine Werbe- oder Analyse-Tracker verwendet.","Your account needs local sign-in storage. The sampler saves projects and imported samples in this browser on this device. There is no cloud sync. No advertising or analytics trackers are used."],["Informationen zur Verarbeitung von Daten lesen","Read the data processing information"],["Verstanden, weiter","Understood, continue"],["Abbrechen","Cancel"],["WEB-SAMPLER","WEB SAMPLER"],["Unbenannter Beat","Untitled beat"],["Importierter Beat","Imported beat"],["Projekt und importierte Samples auf diesem Gerät gespeichert.","Project and imported samples saved on this device."],["Das Projekt konnte nicht gespeichert werden. Prüfe den verfügbaren Browserspeicher und exportiere eine Sicherung.","Could not save this project. Check available browser storage and export a backup."],["Neues Sampler-Projekt bereit. Änderungen werden automatisch auf diesem Gerät gespeichert.","New sampler project ready. Changes are saved automatically on this device."],["Sounds und gespeicherte Projekte werden geladen …","Loading sounds and saved projects …"],["Gespeichertes Projekt einschließlich importierter Samples wiederhergestellt.","Saved project restored, including your imported samples."],["Bereit. Änderungen und importierte Samples werden lokal auf diesem Gerät gespeichert.","Ready. Changes and imported samples are saved locally on this device."],["Pattern geleert. Diese Änderung wird lokal gespeichert.","Pattern cleared. This change will be saved locally."],["Sample geladen. Es wird lokal mit diesem Projekt gespeichert.","Sample loaded. It will be saved locally with this project."],["Projekt-Sicherung einschließlich importierter Samples exportiert.","Project backup exported, including imported samples."],["Projekt-Sicherung importiert.","Project backup imported."],["Projekt aus diesem Browser gelöscht.","Project deleted from this browser."],["Dieses Projekt und seine importierten Samples aus diesem Browser löschen?","Delete this project and its imported samples from this browser?"],["Projektdatei ist zu groß.","Project file is too large."],["Ungültiges Sampler-Projekt.","Invalid sampler project."],["Ungültiges Sample.","Invalid sample."],["Sample ist länger als 30 Sekunden.","Sample exceeds 30 seconds."],["Sounds konnten nicht geladen werden","Could not load sounds"],["Ein Sample konnte nicht geladen werden","Could not load a sample"],["Aus Ideen wird Sound.","Turn ideas into sound."],["Impressum & Verarbeitung von Daten","Legal notice & data processing"],["WÄHLE DEINEN WORKFLOW","CHOOSE YOUR WORKFLOW"],["Dein Studio. Dein Sound.","Your studio. Your sound."],["Spiele Pads, importiere deine Sounds und baue einen Beat.","Play pads, import your sounds and build a beat."],["Sampler öffnen ↗","Open sampler ↗"],["Arrangiere deine Tracks und entwickle deine Ideen weiter.","Arrange your tracks and develop your ideas further."],["In Entwicklung","In development"],["Dieses Feature wird aktuell noch entwickelt.","This feature is currently under development."],["Du kannst bereits den Sampler nutzen. Das Songstudio wird in einem zukünftigen Update verfügbar.","You can already use the sampler. Songstudio will become available in a future update."],["Browser-Version · Die Android-APK selbst läuft nicht in diesem Browser.","Browser version · The Android APK itself does not run in this browser."],["← Studio-Menü","← Studio menu"],["Das Songstudio ist gesperrt, während es für den Browser entwickelt wird.","Songstudio is locked while it is being developed for the browser."],["Eine APK wird außerhalb des Play Stores installiert. Sichere bestehende Projekte vor einem Update. Die aktuelle Android-Version verlangt innerhalb der App noch kein Konto.","An APK is installed outside the Play Store. Back up existing projects before updating. The current Android build does not yet require an account inside the app."],["Studio erscheint bald","Studio coming soon"],["APK erscheint bald","APK coming soon"],["Das Online-Studio ist noch nicht verfügbar. Wir bereiten den Start vor.","The online studio is not available yet. We are preparing the launch."],["APK-Downloads sind noch nicht verfügbar. Wir bereiten den Start vor.","APK downloads are not available yet. We are preparing the launch."],["Erstelle dein Profil. Studio-Zugang und APK-Downloads werden später verfügbar.","Create your profile. Studio access and APK downloads will become available later."],["Dein Profil und dein einmaliger Benutzername sind der erste Schritt. Studio-Zugang und APK-Downloads werden später freigeschaltet.","Your profile and unique username are your first step. Studio access and APK downloads will open later."],["Studio-Zugang und APK-Downloads werden vorbereitet.","Studio access and APK downloads are being prepared."],["© 2026 ZYNORA Studio · Vor dem Start","© 2026 ZYNORA Studio · Pre-launch"],["Vor dem Start · 5. November 2026. Diese Website wird über GitHub Pages gehostet. Studio-Zugang und APK-Downloads sind pausiert. Mailversand und Kontolöschverfahren werden noch fertig eingerichtet.","Pre-launch · 5 November 2026. This website is hosted on GitHub Pages. Studio access and APK downloads are paused. Mail delivery and account deletion procedures are still being finalized."],["Discord beitreten","Join Discord"],["Bewerbungen","Applications"],["Tritt zuerst unserem Discord-Server bei. Öffne dann den Kanal und wähle eine Kategorie, um dein privates Ticket zu erstellen. Du brauchst ein Discord-Konto und Zugriff auf den Kanal.","Join our Discord server first, then open the channel and choose a category to create your private ticket. A Discord account and channel access are required."],["Allgemeiner Support","General support"],["Fragen zum Bot oder zum Discord-Server.","Questions about the bot or the Discord server."],["Fehler melden","Bug report"],["Etwas in der App oder auf dem Server funktioniert nicht? Beschreibe uns, was passiert ist.","Something is not working in the app or on the server? Tell us what happened."],["App-Support","App support"],["Erhalte Hilfe zu ZYNORA Studio und seinen Funktionen.","Get help with ZYNORA Studio and its features."],["Moderator","Moderator"],["Hilf dabei, unsere Community zu betreuen und den Server einladend zu halten.","Help look after our community and keep the server welcoming."],["Entwickler","Developer"],["Bewirb dich, um ZYNORA Studio mitzuentwickeln und zu verbessern.","Apply to help build and improve ZYNORA Studio."],["Beta-Tester","Beta tester"],["Teste neue Funktionen und teile hilfreiches Feedback und Fehlerberichte.","Test new features and share clear feedback and bug reports."],["WIR HELFEN DIR WEITER","WE ARE HERE TO HELP"],["Du brauchst","Need a"],["Hilfe?","hand?"],["Wähle, wobei du Hilfe brauchst. Unser Team hilft dir in privaten Discord-Tickets.","Choose what you need help with. Our team handles support in private Discord tickets."],["Helpdesk öffnen","Open help desk"],["Dein nächster Schritt","Your next step"],["Zum Support-Kanal","Go to the support channel"],["Die Website öffnet den Helpdesk-Kanal. Erstelle dort dein Ticket über den passenden Open-Button. Teile niemals Passwörter oder Bestätigungscodes in einem Ticket.","The website opens the help-desk channel. Create your ticket there using the matching Open button. Never share passwords or verification codes in a ticket."],["GESTALTE MIT UNS","BUILD WITH US"],["Deine Ideen.","Your ideas."],["Unser Team.","Our team."],["Du möchtest mitmachen? Wähle eine Rolle und stelle dich in einem privaten Bewerbungsticket auf Discord vor.","Want to get involved? Choose a role and introduce yourself in a private application ticket on Discord."],["Bewerbungen öffnen","Open applications"],["So bewirbst du dich","How to apply"],["Zum Bewerbungskanal","Go to the application channel"],["Wähle im Kanal Mod application, developer application oder Beta-tester. Das Team bespricht dort die Rolle und die nächsten Schritte mit dir.","Choose Mod application, developer application or Beta-tester in the channel. The team will discuss the role and next steps with you there."],["EIN ORT FÜR DEINEN SOUND","A PLACE FOR YOUR SOUND"],["Triff deine","Meet your"],["Teile deine Sounds auf Discord, hört gemeinsam Musik und vernetze dich mit anderen Kreativen. Erhalte Support oder gestalte mit, was als Nächstes kommt.","Share your sounds on Discord, listen to music together and connect with other creators. Get support or help shape what comes next."],["Community-Illustration mit Klangwellen, Profilen und Chatblasen","Community illustration with sound waves, creator profiles and chat bubbles"],["Wir verwenden notwendigen Browserspeicher für die Anmeldung, deine Sprache und diesen Hinweis. Es gibt keine Werbe- oder Analyse-Tracker. Studio-Projekte bleiben auf diesem Gerät; Cloud-Synchronisation ist nicht aktiv.","We use necessary browser storage for sign-in, your language and this notice. There are no advertising or analytics trackers. Studio projects stay on this device; cloud sync is not active."],["Cookies & Browserspeicher","Cookies & browser storage"],["Mehr erfahren","Read more"],["Verstanden","Understood"],["Auf GitHub Pages verwendet der deutsche Sprachhinweis deine Browsersprache und Zeitzone. Dein tatsächlicher Standort wird nicht ermittelt. Es werden weder GPS noch ein externer IP-Ortungsdienst verwendet. Deine Sprachwahl wird lokal gespeichert.","On GitHub Pages, the German-language suggestion uses your browser language and time zone. It does not determine your actual location. No GPS or external IP location service is used. Your language choice is stored locally."],["8. Discord-Community, Support und Bewerbungen","8. Discord community, support and applications"],["Discord ist über gewöhnliche externe Links verknüpft; es ist kein Discord-Widget eingebettet. Beim Anklicken öffnet sich Discord. Dort verarbeitet Discord Verbindungs- und Kontoinformationen nach seiner eigenen Datenschutzerklärung. Unter Umständen musst du dem Server beitreten, bevor ein Kanal zugänglich ist.","Discord is linked using ordinary external links; no Discord widget is embedded. Clicking a link opens Discord, where Discord processes connection and account information under its own privacy policy. You may need to join the server before a channel becomes accessible."],["Datenschutzerklärung von Discord","Discord privacy policy"],["Wenn du unser Team über ein Support- oder Bewerbungsticket kontaktierst, verarbeiten wir deinen Discord-Benutzernamen, Nachrichten und von dir geteilte Dateien zur Bearbeitung deiner Anfrage oder Bewerbung. Tickets sind für die für diesen Kanal berechtigten Teammitglieder und Server-Bots sichtbar. Teile nur erforderliche Informationen und keine Passwörter oder Bestätigungscodes. Für Löschanfragen und Fragen zur Aufbewahrung von Tickets kontaktiere den unten genannten Website-Inhaber.","When you contact our team through a support or application ticket, we process your Discord username, messages and any files you choose to share to handle your request or application. Tickets are visible to the team members and server bots authorized for that channel. Share only what is needed; never include passwords or verification codes. For deletion requests and questions about ticket retention, contact the website owner below."],["Support erfolgt zur Bereitstellung des angefragten Dienstes oder zur Beantwortung deiner Anfrage (je nach Anfrage Art. 6 Abs. 1 Buchst. b oder f DSGVO). Die Teilnahme an der Community ist freiwillig. Für dringende rechtliche oder Datenschutzanfragen steht dir auch die unten genannte Kontakt-E-Mail zur Verfügung.","We handle support to provide the requested service or respond to your enquiry (Article 6(1)(b) or (f) GDPR, depending on the request). Community participation is optional. Do not use Discord for urgent legal or privacy requests; the contact email below is also available."],["9. Speicherhinweis und Einstellungen","9. Storage notice and settings"],["Der Banner informiert über notwendigen Speicher. Er aktiviert kein optionales Tracking. Die Bestätigung wird als zynora-cookie-notice-v1 in localStorage gespeichert, bis du die Browserdaten löschst. Sprache und Anmeldesitzung verwenden ebenfalls localStorage. Sampler-Projekte verwenden IndexedDB, wenn das Studio verfügbar ist. Über Cookies & Speicher im Footer kannst du den Hinweis erneut öffnen. Diese Website setzt keine optionalen Analyse- oder Werbe-Cookies.","The banner informs you about necessary storage. It does not enable optional tracking. Its acknowledgement is stored as zynora-cookie-notice-v1 in localStorage until you clear browser data. Language and sign-in settings also use localStorage. Sampler projects use IndexedDB when the studio is available. You can reopen the notice using Cookies & storage in the footer. No optional analytics or advertising cookies are set by this website."],["Cookies & Speicher","Cookies & storage"],["dein sound.","your sound."],["unsere ","our "],["community.","community."],["GEMEINSAM MEHR ERLEBEN","CREATE TOGETHER"],["DISCORD · SOUNDS · COMMUNITY","DISCORD · SOUNDS · COMMUNITY"],["Community anzeigen","Show community"],["Discord beitreten ↗","Join Discord ↗"],["Zynora Studio öffnen ↗","Open Zynora Studio ↗"],["Community.","Community."],["Vor dem Start · 5. November 2026. Diese Website wird über GitHub Pages gehostet. Konto-E-Mails werden über Resend versendet. Studio-Zugang und APK-Downloads bleiben pausiert. Cloud-Synchronisation von Projekten und automatische Kontolöschung sind noch nicht aktiv.","Pre-launch · 5 November 2026. This website is hosted on GitHub Pages. Account emails are sent through Resend. Studio access and APK downloads remain paused. Cloud project sync and automatic account deletion are not active yet."],["GitHub Pages hostet die öffentliche Website und verarbeitet Verbindungsinformationen wie IP-Adresse, Anfragezeit und angefragte Ressource zur Auslieferung und Sicherheit. Supabase stellt Anmeldung, Profile und privaten Profilbild-Speicher im Projekt NEXORA STUDIO bereit. APK-Downloads bleiben deaktiviert.","GitHub Pages hosts the public website and processes connection information such as IP address, request time and requested resource for delivery and security. Supabase provides authentication, profiles and private avatar storage in the NEXORA STUDIO project. APK downloads remain disabled."],["Resend (Plus Five Five, Inc.) versendet in unserem Auftrag Konto-Bestätigungen, Anmeldelinks und E-Mails zum Zurücksetzen von Passwörtern. Dafür werden Empfängeradresse, erforderlicher Nachrichteninhalt einschließlich Bestätigungslinks oder Codes und technische Zustelldaten verarbeitet. Absender ist support@zynora-studio.com; Antworten gehen an zynora-studio@outlook.de. Die Versandadresse ist kein separates Support-Postfach. Die Verarbeitung dient der angefragten Kontofunktion und dem sicheren Betrieb (Art. 6 Abs. 1 Buchst. b und f DSGVO).","Resend (Plus Five Five, Inc.) sends account confirmation, sign-in and password-reset emails on our behalf. This requires the recipient address, the necessary message content including verification links or codes, and technical delivery data. The sender is support@zynora-studio.com; replies are directed to zynora-studio@outlook.de. This sending address does not provide a separate support inbox. Email processing serves the requested account function and secure operation (Article 6(1)(b) and (f) GDPR)."],["Als Versandregion ist Irland ausgewählt. Resend beschreibt in seiner Datenschutzerklärung auch eine Verarbeitung in den USA; die Versandregion garantiert deshalb keine ausschließlich im EWR stattfindende Verarbeitung. Öffnungs- und Klicktracking für E-Mails sind für diese Domain nicht aktiviert. Gib Bestätigungslinks oder Codes nicht an andere Personen weiter.","Ireland is selected as the sending region. Resend also describes processing in the United States in its privacy policy; the selected sending region is not a guarantee that all processing stays within the EEA. Email open and click tracking are not enabled for this domain. Do not forward confirmation links or codes to other people."],["Datenschutzerklärung von Resend","Resend privacy policy"],["Bitte prüfe dein E-Mail-Postfach und bestätige deine Adresse. Schau auch in deinem Spam-Ordner nach. Dein Benutzername wird beim Speichern des Profils verbindlich vergeben.","Please check your inbox and confirm your email address. Please also check your spam or junk folder. Your username is reserved when you save your profile."],["Falls ein Konto existiert, wurde ein Link zum Zurücksetzen angefordert. Bitte prüfe dein Postfach und auch deinen Spam-Ordner.","If an account exists, a password reset link has been requested. Please check your inbox and your spam or junk folder."],["Bestätigung erneut senden","Resend confirmation email"],["Für diese E-Mail-Adresse besteht bereits ein Konto. Bitte melde dich an oder setze dein Passwort zurück.","An account already exists for this email address. Please sign in or reset your password."],["Wenn deine E-Mail-Adresse noch nicht registriert ist, erhältst du eine Bestätigung. Prüfe dein Postfach und deinen Spam-Ordner. Falls du bereits ein Konto hast, melde dich an oder setze dein Passwort zurück.","If your email address is not already registered, you will receive a confirmation. Check your inbox and spam or junk folder. If you already have an account, sign in or reset your password."],["Falls dein Konto noch nicht bestätigt ist, wurde eine Bestätigung angefordert. Schau auch in deinem Spam-Ordner nach. Bereits bestätigte Konten können sich direkt anmelden.","If your account is still unconfirmed, a confirmation email has been requested. Please also check your spam or junk folder. Already confirmed accounts can sign in directly."],["Konto löschen","Delete account"],["Mein Konto löschen","Delete my account"],["Kontolöschung zurücknehmen","Cancel account deletion"],["Konto wirklich löschen?","Delete your account?"],["E-Mail-Adresse bestätigen","Confirm your email address"],["Kontolöschung vormerken","Schedule account deletion"],["Fordere die dauerhafte Löschung deines Kontos, Profils und deiner hochgeladenen Dateien nach 30 Tagen an. Innerhalb dieser Frist kannst du die Löschung zurücknehmen. Exportiere vorher alles, was du behalten möchtest.","Request permanent deletion of your account, profile and uploaded files after 30 days. You can cancel during this period. Export anything you want to keep first."],["Dein Konto ist zur Löschung vorgemerkt. Die Bearbeitung ist pausiert. Du kannst die Löschung vor dem unten angezeigten Termin zurücknehmen.","Your account is scheduled for deletion. Editing is paused. You can cancel before the deletion date shown below."],["Dein Konto, dein Profil und deine hochgeladenen Dateien werden nach 30 Tagen dauerhaft gelöscht. Innerhalb dieser Frist kannst du die Löschung zurücknehmen. Es werden jetzt noch keine Daten gelöscht.","Your account, profile and uploaded files will be permanently deleted after 30 days. You can cancel during this period. No data will be deleted immediately."],["Lokale Sampler-Projekte auf deinen Geräten und exportierte Dateien sind keine Cloud-Daten. Lösche die Browserdaten dieser Website auf jedem Gerät, um diese Kopien zu entfernen.","Local sampler projects on your devices and files you exported are not cloud data. Clear this website’s browser data on each device to remove those copies."],["Bitte melde dich erneut an.","Please sign in again."],["Bitte gib die E-Mail-Adresse deines Kontos ein.","Please enter your account’s email address."],["Die Löschung ist für den angezeigten Termin vorgemerkt. Du kannst sie bis dahin zurücknehmen.","Deletion is scheduled for the date shown. You can cancel before then."],["Die Kontolöschung wurde zurückgenommen.","Account deletion has been cancelled."],["Die Kontolöschung wurde bereits gestartet und kann nicht mehr zurückgenommen werden.","Account deletion is already being processed and cannot be cancelled."],["Dein Konto ist zur Löschung vorgemerkt. Nimm die Löschung zuerst in deinem Profil zurück.","Your account is scheduled for deletion. Cancel deletion in your profile first."],["Vor dem Start · 5. November 2026. Diese Website wird über GitHub Pages gehostet. Konto-E-Mails werden über Resend versendet. Studio-Zugang und APK-Downloads bleiben pausiert. Die Kontolöschung kann im Profil mit einer Frist von 30 Tagen angefordert werden. Cloud-Projektsynchronisierung ist noch nicht aktiv.","Pre-launch · 5 November 2026. This website is hosted on GitHub Pages. Account emails are sent through Resend. Studio access and APK downloads remain paused. Account deletion can be requested in your profile with a 30-day waiting period. Cloud project sync is not active yet."],["Du kannst unter Mein Profil die Löschung deines Kontos anfordern. Dabei wird eine Frist von 30 Tagen angezeigt. Während dieser Frist sind Änderungen an Profilen, Projekten und Uploads gesperrt; die Anmeldung zum Zurücknehmen der Löschung bleibt möglich. Nach Ablauf entfernt eine stündliche Bereinigung Konto, Profil, hochgeladene Dateien und zugehörige Projektdaten aus den aktiven Systemen. Fehlerhafte Löschungen werden erneut versucht. Bereits exportierte Dateien und lokale Browserkopien auf deinen Geräten werden dadurch nicht gelöscht. Technische Protokolle und Sicherungen unterliegen den Aufbewahrungsfristen der jeweiligen Anbieter; gesetzliche Aufbewahrungspflichten bleiben unberührt. Für Auskunft, Berichtigung, Löschung, Einschränkung, Übertragbarkeit oder Widerspruch, soweit anwendbar, kannst du uns auch per E-Mail kontaktieren. Du kannst dich bei einer zuständigen Datenschutzaufsichtsbehörde beschweren, etwa dem Hessischen Beauftragten für Datenschutz und Informationsfreiheit.","You can request account deletion under My profile. A 30-day waiting period is shown. During this period, profile edits, project changes and uploads are blocked; you can still sign in to cancel deletion. After the deadline, an hourly cleanup removes your account, profile, uploaded files and associated project data from active systems. Failed deletions are retried. Exported files and local browser copies on your devices are not removed by this process. Technical logs and backups follow the respective providers’ retention periods; legal retention duties remain unaffected. You may also contact us by email for access, rectification, erasure, restriction, portability or objection where applicable. You may complain to a competent data protection authority, including the Hessian Commissioner for Data Protection and Freedom of Information."],["Mit Discord anmelden","Continue with Discord"],["oder per E-Mail","or use email"],["Discord wird geöffnet …","Opening Discord …"],["Bitte lies zuerst die Informationen zur Verarbeitung von Daten.","Please read the data processing information first."],["Die Discord-Anmeldung wurde abgebrochen oder ist fehlgeschlagen. Bitte versuche es erneut oder melde dich per E-Mail an.","Discord sign-in was cancelled or failed. Please try again or sign in with email."],["Discord-Anmeldung ist derzeit nicht verfügbar. Bitte nutze die Anmeldung per E-Mail.","Discord sign-in is currently unavailable. Please use email sign-in."],["Bei der freiwilligen Anmeldung mit Discord erhält Supabase deine Discord-Kennung, Profilinformationen und die zugehörige E-Mail-Adresse. Für die Anmeldung werden nur die Bereiche identify und email angefordert; es werden keine Rechte zum Lesen deiner Nachrichten, Verwalten von Servern oder Hinzufügen des Bots angefordert. Die Anmeldung erfolgt über Discord und Supabase; Passwörter für Discord werden nicht auf dieser Website eingegeben. Eine bereits vorhandene bestätigte E-Mail-Adresse wird demselben Konto zugeordnet. Deinen eindeutigen ZYNORA-Benutzernamen wählst du anschließend im Profil. Die Verarbeitung dient der von dir gewählten Anmeldung (Artikel 6 Absatz 1 Buchstabe b DSGVO). Du kannst weiterhin die Anmeldung per E-Mail verwenden.","When you choose to sign in with Discord, Supabase receives your Discord ID, profile information and associated email address. Sign-in requests only the identify and email scopes; it does not request permission to read your messages, manage servers or add the bot. Authentication takes place through Discord and Supabase; you do not enter your Discord password on this website. An existing confirmed email address is associated with the same account. You then choose your unique ZYNORA username in your profile. Processing provides the sign-in method you requested (Article 6(1)(b) GDPR). Email sign-in remains available."],["Neue Discord-Registrierungen werden auf unserem Discord-Server mit deiner Discord-Erwähnung und dem Erstellungszeitpunkt angekündigt. Du kannst dich auch per E-Mail registrieren.","New Discord registrations are announced in our Discord server with your Discord mention and registration time. You can also register by email."],["Wenn du ein neues Website-Konto mit Discord erstellst, sendet unser Bot eine englische Registrierungsnachricht in den dafür vorgesehenen Kanal unseres Discord-Servers. Sie enthält deine Discord-Erwähnung, Discord-ID und den Erstellungszeitpunkt deines Website-Kontos. E-Mail-Adressen, Passwörter und IP-Adressen werden nicht in die Meldung aufgenommen. Personen mit Zugriff auf diesen Discord-Kanal können die Nachricht sehen. Erneutes Anmelden und das Verbinden von Discord mit einem bereits vorhandenen E-Mail-Konto lösen keine neue Registrierungsnachricht aus. Für diesen Ablauf verarbeiten Supabase und BotGhost die erforderlichen Kennungen und Zustellinformationen. Ungesendete Meldungen werden bei einem Ausfall für einen späteren Versuch aufbewahrt; Zustellprotokolle werden nach sieben Tagen entfernt. Die Zuordnung zur Discord-Nachricht bleibt bestehen, damit der Bot bei der endgültigen Kontolöschung auch deren Entfernung anfordern kann. Die Entfernung erfolgt beim nächsten erfolgreichen Bot-Lauf und setzt die erforderlichen Discord-Berechtigungen voraus. Die Registrierung per E-Mail bleibt als Alternative verfügbar.","When you create a new website account with Discord, our bot posts an English registration notification in the designated channel of our Discord server. It contains your Discord mention, Discord ID and the creation time of your website account. Email addresses, passwords and IP addresses are not included. People with access to that Discord channel can see the notification. Signing in again or connecting Discord to an existing email account does not create another registration announcement. Supabase and BotGhost process the necessary identifiers and delivery information for this workflow. Undelivered notifications are retained during an outage for a later attempt; delivery logs are removed after seven days. The Discord message reference is retained so the bot can request removal of the notification when your account is permanently deleted. Removal happens on the next successful bot run and requires the necessary Discord permissions. Email registration remains available as an alternative."],["Beta-Version","Beta version"],["Beta-Version öffnen ↗","Open beta version ↗"],["Dein Beta-Zugang ist aktiv. Der Sampler ist verfügbar; das Song Studio bleibt gesperrt.","Your beta access is active. The sampler is available; Song Studio remains locked."],["Der Sampler ist nur für eingeladene Betatester verfügbar. Song Studio und APK-Downloads bleiben gesperrt.","The sampler is available only to invited beta testers. Song Studio and APK downloads remain paused."],["Für eingeladene Betatester speichern wir die Discord-ID, den freischaltenden Administrator, den Zeitpunkt und den Zugangsstatus. Der Bot sendet bei der Freischaltung eine Einladungs-DM. Melde dich mit dem ausgewählten Discord-Konto an, um die Beta zu nutzen. Das Song Studio bleibt gesperrt.","For invited beta testers, we store the Discord ID, granting administrator, grant time and access status to control sampler access. The bot sends an invitation DM when access is granted. Sign in with the selected Discord account to use the beta. Song Studio stays locked."],["Beta-Zugang erforderlich. Bitte melde dich mit deinem freigeschalteten Discord-Konto an.","Beta access required. Please sign in with your invited Discord account."],["Mach Musik.","Make music."],["Teile deinen Sound.","Share your sound."],["Baue deinen Beat im Sampler. Teile eigene Tracks, entdecke neue Artists und finde deine nächste Inspiration.","Build your beat in the sampler. Share your own tracks, discover new artists and find your next inspiration."],["Eine Idee. Dein eigener Groove.","One idea. Your own groove."],["Dein Profil verbindet deine Musik mit der Community. Der Sampler ist für eingeladene Betatester verfügbar.","Your profile connects your music with the community. The sampler is available to invited beta testers."],["Höre Musik im Music Player oder werde im Sampler kreativ.","Listen in the Music Player or create music in the sampler beta."],["Entdecke öffentliche Songs, Samples und Loops im Music Player. Folge Kreativen und teile deine Musik auf deinem öffentlichen Musikprofil.","Discover public songs, samples and loops in the Music Player. Follow creators and share your own music on your public music profile."],["Deine Musik.","Your music."],["Deine","Your"],["Community.","community."],["Entdecke Musik, Samples und Loops aus der Community.","Discover community music, samples and loops."],["Top Songs","Top Songs"],["Neu","New"],["Personen","People"],["Gefolgte Profile","Following"],["+ Musik hochladen","+ Upload music"],["Suchen","Search"],["Musik veröffentlichen","Publish music"],["Öffentlich hochladen","Publish publicly"],["Folgen","Follow"],["Gefolgt ✓","Following ✓"],["Veröffentlichungen","Releases"]];